css:
/* Pink Love: big wrapping thread titles, with each thread wearing its project as a pill. */

/* Projects are shown as pills, so icons, labels and group headers step aside. */
[data-t3-part="sidebar"] [data-t3-part="project-icon"],
[data-t3-part="sidebar"] [data-t3-part="project-group-header"],
[data-t3-part="thread-row"] [data-t3-part="project-name"] {
  display: none;
}

/* Room above each row for its pill to sit on the edge. */
[data-t3-part="sidebar"] [data-t3-part="thread-item"] {
  padding-top: 11px;
  padding-bottom: 3px;
}

[data-t3-part="sidebar"] [data-t3-part="thread-row"] {
  height: auto;
  overflow: visible;
  border: 1px solid color-mix(in oklab, var(--app-theme-accent) 22%, transparent);
  border-radius: 14px;
}
[data-t3-part="sidebar"] [data-t3-part="thread-row"][aria-current="page"] {
  border-color: color-mix(in oklab, var(--app-theme-accent) 55%, transparent);
  box-shadow: 0 6px 18px -10px color-mix(in oklab, var(--app-theme-accent) 70%, transparent);
}

/* Card rows grow with their title instead of keeping a fixed height. */
[data-t3-part="sidebar"] [data-t3-part="thread-body"] {
  height: auto;
  padding-top: 10px;
  padding-bottom: 9px;
}

/* Slim rows (settled, legacy sidebar) wrap too, status pinned to the first line. */
[data-t3-part="sidebar"] [data-t3-part="thread-row"][data-t3-variant="slim"],
[data-t3-part="project-group-threads"] [data-t3-part="thread-row"] {
  min-height: 2.5rem;
  align-items: flex-start;
  padding-top: 11px;
  padding-bottom: 9px;
}

[data-t3-part="sidebar"] [data-t3-part="thread-title"] {
  overflow: visible;
  text-overflow: clip;
  white-space: normal;
  overflow-wrap: anywhere;
  text-wrap: pretty;
  font-size: 15px;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.01em;
}

/* The project pill, tucked onto the top edge of every thread. */
[data-t3-part="sidebar"] [data-t3-part="thread-project"] {
  display: inline-block;
  position: absolute;
  top: -9px;
  left: 10px;
  z-index: 20;
  max-width: calc(100% - 20px);
  height: 18px;
  padding: 0 8px 0 7px;
  overflow: hidden;
  border-radius: 999px;
  background: linear-gradient(
    120deg,
    var(--app-theme-accent),
    color-mix(in oklab, var(--app-theme-accent) 62%, white)
  );
  box-shadow:
    0 0 0 2px var(--app-theme-sidebar),
    0 3px 8px -3px color-mix(in oklab, var(--app-theme-accent) 80%, transparent);
  color: var(--app-theme-accent-foreground);
  font-size: 10.5px;
  font-weight: 700;
  line-height: 18px;
  letter-spacing: 0.02em;
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: none;
}
:root:not(.dark) [data-t3-part="sidebar"] [data-t3-part="thread-project"] {
  background: linear-gradient(120deg, #d1206a, #f2649f);
  color: #fff;
}
[data-t3-part="sidebar"] [data-t3-part="thread-project"]::before {
  content: "\2665";
  margin-right: 4px;
  font-size: 9px;
}

/* Legacy sidebar: threads sit flush once their group header is hidden, and a
   status label gets its own line above the title. */
[data-t3-part="project-group-threads"] {
  margin-inline: 0;
  padding-inline: 4px;
  border-left: 0;
}
[data-t3-part="project-group-threads"] [data-t3-part="thread-body"] {
  flex-wrap: wrap;
  row-gap: 2px;
}
[data-t3-part="project-group-threads"] [data-t3-part="thread-title"] {
  flex-basis: 100%;
}
